module StoneGame(\n    input [3:0] n,\n    input [31:0] a0, a1, a2, a3, a4, a5, a6, a7,\n    output reg win\n);\n    // Internal array\n    wire [31:0] arr [0:7];\n    assign arr[0] = a0;\n    assign arr[1] = a1;\n    assign arr[2] = a2;\n    assign arr[3] = a3;\n    assign arr[4] = a4;\n    assign arr[5] = a5;\n    assign arr[6] = a6;\n    assign arr[7] = a7;\n\n    // Sorting and processing\n    reg [31:0] temp [0:7];\n    integer i, j, k;\n    reg [31:0] swap;\n    reg [2:0] dup_count;\n    reg [31:0] dup_value;\n    reg triple;\n    reg lose_condition;\n    reg found_dup_value_minus_one;\n    reg [31:0] sum_val;\n    reg [31:0] base;\n    reg [31:0] S;\n\n    always @(*) begin\n        // Initialize with padding\n        for (i = 0; i < 8; i = i + 1) begin\n            if (i < n)\n                temp[i] = arr[i];\n            else\n                temp[i] = 32'hFFFF_FFFF;\n        end\n\n        // Bubble sort\n        for (i = 0; i < 8; i = i + 1) begin\n            for (j = 0; j < 7 - i; j = j + 1) begin\n                if (temp[j] > temp[j+1]) begin\n                    swap = temp[j];\n                    temp[j] = temp[j+1];\n                    temp[j+1] = swap;\n                end\n            end\n        end\n\n        // Duplicate detection\n        dup_count = 0;\n        dup_value = 0;\n        triple = 0;\n        lose_condition = 0;\n        \n        for (i = 0; i < n-1; i = i + 1) begin\n            if (temp[i] == temp[i+1]) begin\n                dup_count = dup_count + 1;\n                dup_value = temp[i];\n                if (i+2 < n && temp[i] == temp[i+2])\n                    triple = 1;\n            end\n        end\n\n        if (triple || dup_count >= 2)\n            lose_condition = 1;\n        else if (dup_count == 1) begin\n            if (dup_value == 0)\n                lose_condition = 1;\n            else begin\n                found_dup_value_minus_one = 0;\n                for (k = 0; k < n; k = k + 1) begin\n                    if (temp[k] == dup_value - 1)\n                        found_dup_value_minus_one = 1;\n                end\n                if (found_dup_value_minus_one)\n                    lose_condition = 1;\n            end\n        end\n\n        // Parity calculation\n        sum_val = 0;\n        for (i = 0; i < n; i = i + 1)\n            sum_val = sum_val + temp[i];\n        base = (n * (n-1)) >> 1;\n        S = sum_val - base;\n\n        // Win determination\n        win = lose_condition ? 0 : S[0];\n    end\nendmodule